(436, 'Android Ai Box 8GBRAM 128GBMEMORY', 'https://res.cloudinary.com/dmkxx68km/image/upload/v1722419816/grufskrh0rbjz14njgjo.jpg', 436, '·Smooth and intelligent Android 12.0 operating system,\n·Install any app you like from Google Play Store, YouTube, Netflix, Spotify, Google Maps, Waze, Yandex Navi, Google Assistant, and more.\n·Integrated GPS module for precise online/offline navigation, GPS/GLONASS/Beidou\n·Built-in GPS antenna, compatible with some original car GPS signals\n·Original car radio volume and box navigation volume mixing are supported\n·Bluetooth HandsFreeLink is configured\n·Original touchscreen, steering wheel and center console joystick/button operation are configured\n·Compatible with original car microphone and original car speaker \n·Automatic recognition of day and night modes\n·Left and right peptide switching\n·Global weather forecast is available\n·Compatible with multiple screen sizes and resolutions\n·Built-in wireless CartPlay and wireless Android Auto\n·Software can be upgraded through TF card\n·4K HD video', '2024-07-31 01:57:22', '', 'androidplayer', 'grufskrh0rbjz14njgjo', '', 'androidPlayer', '', 'Android_Ai_Box', NULL),
(885, 'DM SERIES Qualcomm Snapdragon 665 Toyota Alphard Vellfire AGH30 OEM Android Screen 2K QLED', 'https://res.cloudinary.com/dmkxx68km/image/upload/v1728034058/joxslw4gckzkyzmydp5j.webp', 885, 'SPECIFICATIONS:\nSystem:Android 10\nCPU: Qualcomm Snapdragon 665\n8 x ARM KYRO @ 2.02GHz\nGPU: ADRENO 610 950MHz\nRAM: 8GB DDR3 (ROM: 256GB)\nBluetooth: Bluetooth 5.0 (A2DP)\nWifi: 5G/2.4G\nSupport 4G LTE (Build-in Sim Card Slot)\nScreen: Anti-Glare Screen + 2.5D QLED Screen\nResolution: 2K QLED 2000×1200 Pixel\n\nDual App Function:\nFront Player (Waze,Google map)\nRear Moniter (youtube,Live tv or etc)\n\nNew Q LED Screen\nBuilt-in Sim Card Slot\nBuilt-in DTS Sound System\nBuilt-in HDMI Output\nBuilt-in CarPlay\nBuilt-in Android Auto\nExternal Mic\nDigital FM with RDS Function\nDual-Zone Funtion\nDual App Function\nSplit Screen Function\n*Optional 3D 360 Camera System With Touch Screen Control', '2024-10-04 09:27:59', '', 'alphardvellfire', 'joxslw4gckzkyzmydp5j', '', '', '11.6Inch | 8GB RAM + 256GB ROM', '', NULL),
